{"tool":"brick.build","input":{"seed":1,"code":"script({title:'Imperial I-class — Devastator',description:'A 144-stud Imperial Star Destroyer with a razor-edged layered hull, recessed machinery trenches, eight heavy turbolaser batteries, terraced command citadel, twin shield generators and seven illuminated aft exhausts. Two compact black cradles support the ship above its recessed ventral docking bay.',palette:{hull:'light bluish grey',machinery:'dark bluish grey',shadow:'black'}});
const H='light bluish grey',D='dark bluish grey',B='black';
const p=(part,x,y,z,colour=H,turn=0)=>place({part,at:[x,y,z],colour,turn});
section('Display cradles',[52,112].map(z=>[box({at:[-14,0,z-5],size:[28,3,10],colour:B,top:'tile'}),box({at:[-4,3,z-3],size:[8,23,6],colour:B}),box({at:[-10,22,z-3],size:[20,4,6],colour:B})]));
const underside=[],core=[],armour=[],rim=[],trench=[];
for(let i=0;i<24;i++){
 const z=i*6,a=2*i;
 if(a>0){
  core.push(box({at:[-a,27,z],size:[2*a,10,6],colour:H,supports:8}));
  core.push(floor({at:[-a,37,z],size:[2*a,6],colour:H}));
  for(let x=-a;x<a;x+=2){
   underside.push(p('3021',x,26,z,H,90),p('3021',x,26,z+3,H,90));
   for(let dz=0;dz<6;dz+=2){
    const occupied=z+dz>=78&&z+dz<136&&x>=-22&&x<22;
    armour.push(p(occupied?'3022':'3068b',x,38,z+dz,H));
   }
  }
 }
 for(const side of [-1,1]){
  const x=side<0?-a-2:a;
  for(const y of [26,27,37,38])rim.push(p(side<0?'41770a':'41769a',x,y,z,H));
  rim.push(floor({at:[x,26,z+4],size:[2,2],layers:2,colour:H}),floor({at:[x,37,z+4],size:[2,2],layers:2,colour:H}));
  trench.push(box({at:[x,28,z+4],size:[2,9,2],colour:D,texture:'grille'}));
  if(i>1){
   trench.push(p('4070',side<0?-a:a-1,29,z+1,D,side<0?90:270));
   trench.push(p('2877',side<0?-a:a-1,32,z+2,H,90));
   trench.push(p('6141',side<0?-a:a-1,35,z+1,H));
  }
 }
}
section('Connected ventral armour',underside);
section('Internal hull frame and dorsal backing',core);
section('Smooth triangular armour panels',armour);
section('Double blade perimeter',rim);
section('Recessed perimeter machinery',trench);
function citadel(x,z,w,d,y,h){
 const out=[];
 for(let k=0;k<d;k+=4){
  const inset=Math.max(0,6-Math.floor(k/4)*2);
  out.push(box({at:[x+inset,y,z+k],size:[w-2*inset,h,Math.min(4,d-k)],colour:H,texture:'grille',top:'tile'}));
 }
 for(let k=8;k<d-2;k+=4){
  for(const sx of [x-1,x+w]){
   out.push(p('3005',sx,y,z+k,D),p('3062b',sx,y+3,z+k,H),p('3070b',sx,y+6,z+k,H));
  }
 }
 return out;
}
section('Terraced command citadel',[
 citadel(-22,78,44,58,39,9),
 citadel(-17,91,34,43,48,9),
 citadel(-12,103,24,29,57,9),
 box({at:[-6,66,116],size:[12,21,12],colour:H,texture:'grille',top:'tile'}),
 ...[-8,6].map(x=>box({at:[x,66,120],size:[2,18,6],colour:H,top:'tile'})),
 floor({at:[-17,87,114],size:[34,12],layers:2,colour:H}),
 box({at:[-16,89,115],size:[32,5,10],colour:H,top:'tile'}),
 box({at:[-14,90,114],size:[28,2,1],colour:B}),
 floor({at:[-15,92,114],size:[30,1],layers:1,colour:H}),
 ...range(14).map(i=>p('3070b',-14+i*2,92,114,H)),
 ...range(8).map(i=>p('30363',-16+i*4,94,115,H,90)),
 ...range(8).map(i=>p('30363',-16+i*4,94,122,H,270)),
 floor({at:[-16,94,119],size:[32,3],layers:3,colour:H,top:'tile'})
]);
function generator(x){return [
 box({at:[x,97,118],size:[5,3,5],colour:H}),
 p('3941',x+1,100,119,D),
 p('30208',x,103,118,H),
 p('6141',x+2,108,120,H)
];}
section('Shield generators and sensor mast',[
 generator(-13),generator(8),
 box({at:[-2,97,119],size:[4,5,3],colour:H}),
 p('3039',-2,102,119,H),p('3039',0,102,119,H),
 p('3957a',0,105,120,D),
 p('2431',-2,105,121,H)
]);
const detail=[];
// Long service channels lead the eye toward the command tower.
for(const side of [-1,1]){
 for(let z=42;z<77;z+=3){
  const x=side<0?-5:3;
  detail.push(p('2412b',x,39,z,D));
  if(z%2===0)detail.push(p('3069b',x,40,z,H));
 }
 for(let z=84;z<138;z+=6){
  const edge=Math.floor(z/6)*2;
  const x=side<0?-edge+5:edge-7;
  detail.push(p('3020',x,39,z,H),p('2412b',x,40,z,D),p('3069b',x+2,40,z,H),p('3068b',x,40,z+1,H));
 }
}
// Different sizes of flush panel seams and hatches, with generous quiet armour between them.
for(let z=24;z<140;z+=8){
 const hw=2*Math.floor(z/6);
 for(let x=-hw+6;x<hw-5;x+=8){
  if(z>=76&&Math.abs(x)<25)continue;
  detail.push(p('3023b',x,39,z,H),p('3069b',x,40,z,H));
  if((x+z)%3===0)detail.push(p('2412b',x+3,39,z+2,D));
 }
}
for(let tier=0;tier<3;tier++){
 const y=48+tier*9, left=-20+tier*5, right=20-tier*5, z0=90+tier*12, end=130;
 for(let z=z0;z<end;z+=4){
  for(const x of [left,right-2]){
   detail.push(p('3023b',x,y,z,D),p('2412b',x,y+1,z,H));
   detail.push(p('6141',x,y+1,z+2,H));
  }
 }
}
section('Hull panel seams and machinery galleries',detail);
function battery(x,z){return [
 box({at:[x,39,z],size:[6,2,6],colour:D}),
 p('60474',x+1,41,z+1,H),
 box({at:[x+1,42,z+1],size:[4,3,4],colour:H}),
 p('3039',x+1,45,z+1,H),p('3039',x+3,45,z+1,H),
 p('3068b',x+1,45,z+3,H),p('3068b',x+3,45,z+3,H),
 ...[1,4].map(dx=>[p('3024',x+dx,44,z,D),p('3710',x+dx,45,z-3,D,90),p('3070b',x+dx,46,z-3,H)])
];}
section('Eight heavy turbolaser batteries',[-1,1].map(s=>range(4).map(i=>battery(s<0?-30:24,94+i*10))));
// Aft exhausts are built as upright, stud-connected octagonal tunnels.
// Their blue cores face aft; four smaller auxiliary engines sit between the three main bells.
function exhaust(cx,y,r,depth){
 const out=[];const z=144;
 for(let dz=0;dz<depth;dz++){
  for(let dy=-r;dy<=r;dy++){
   const edge=Math.max(1,r-Math.max(0,Math.abs(dy)-Math.floor(r/2)));
   for(let xx=-edge;xx<=edge;xx++){
    const boundary=Math.abs(xx)===edge||Math.abs(dy)===r;
    if(boundary)out.push(p('3005',cx+xx,y+(dy+r)*3,z+dz,dz===depth-1?H:D));
    else if(dz===0)out.push(p('3005',cx+xx,y+(dy+r)*3,z,D));
    else if(dz===1)out.push(p('3005',cx+xx,y+(dy+r)*3,z+dz,'trans light blue'));
   }
  }
 }
 return out;
}
section('Seven aft ion engines',[
 box({at:[-44,27,141],size:[88,12,3],colour:D,texture:'grille'}),
 ...[-25,0,25].map(x=>exhaust(x,26,3,5)),
 ...[-39,-12,12,39].map(x=>exhaust(x,29,1,3)),
 ...range(22).map(i=>p('2412b',-44+i*4,39,141,H))
]);
section('Ventral docking recess',[
 box({at:[-9,20,66],size:[18,6,26],colour:D,open:['front','back','top']}),
 box({at:[-7,24,68],size:[14,2,22],colour:B}),
 ...[-9,7].map(x=>box({at:[x,20,66],size:[2,6,26],colour:H,texture:'grille'})),
 box({at:[-7,20,90],size:[14,6,2],colour:H}),
 ...range(6).map(i=>p('3023b',-6+i*2,22,91,'trans light blue'))
]);"}}
